  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  ADMIN\n  PENGELOLA\n  WISATAWAN\n}\n\nenum Gender {\n  LAKI_LAKI\n  PEREMPUAN\n}\n\nenum DestinationStatus {\n  pending\n  aktif\n  butuh_perbaikan\n  canceled\n}\n\nmodel User {\n  id        Int      @id @default(autoincrement())\n  name      String\n  email     String   @unique\n  password  String\n  role      Role?\n  gender    Gender?\n  domisili  String?\n  photo     String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relasi baru untuk fitur wisatawan\n  savedDestinations SavedDestination[]\n  itineraries       Itinerary[]\n  reviews           Review[]\n  visitedPlaces     VisitedPlace[]\n}\n\nmodel Destination {\n  id          Int               @id @default(autoincrement())\n  name        String\n  description String\n  address     String\n  contact     String?\n  latitude    Float\n  longitude   Float\n  imageUrl    String?\n  // Field tambahan dari pengelola (opsional, bisa ditambah nanti)\n  openTime    String? // format \"08:00\"\n  closeTime   String? // format \"17:00\"\n  ticketPrice Int? // harga tiket dalam rupiah (bisa null = gratis)\n  maxPrice    Int? // harga maksimal (untuk range harga)\n  website     String?\n  visitCount  Int               @default(0)\n  status      DestinationStatus @default(pending)\n  isDeleted   Boolean           @default(false)\n  deletedAt   DateTime?\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  categories     DestinationCategory[]\n  savedBy        SavedDestination[]\n  itineraryItems ItineraryItem[]\n  reviews        Review[]\n  visitedBy      VisitedPlace[]\n}\n\nmodel Category {\n  id        Int      @id @default(autoincrement())\n  name      String   @unique\n  createdAt DateTime @default(now())\n\n  destinations DestinationCategory[]\n  keywords     CategoryKeyword[]\n}\n\nmodel DestinationCategory {\n  id            Int @id @default(autoincrement())\n  destinationId Int\n  categoryId    Int\n\n  destination Destination @relation(fields: [destinationId], references: [id], onDelete: Cascade)\n  category    Category    @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@unique([destinationId, categoryId])\n}\n\nmodel CategoryKeyword {\n  id         Int      @id @default(autoincrement())\n  keyword    String\n  categoryId Int\n  createdAt  DateTime @default(now())\n\n  category Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@unique([categoryId, keyword])\n}\n\n// ============================================================\n// TABEL BARU UNTUK FITUR WISATAWAN\n// ============================================================\n\n// Destinasi yang disimpan oleh wisatawan\nmodel SavedDestination {\n  id            Int      @id @default(autoincrement())\n  userId        Int\n  destinationId Int\n  createdAt     DateTime @default(now())\n\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  destination Destination @relation(fields: [destinationId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, destinationId])\n}\n\n// Rencana perjalanan wisatawan\nmodel Itinerary {\n  id            Int      @id @default(autoincrement())\n  userId        Int\n  title         String   @default(\"Rencana Perjalananku\")\n  totalDistance Float? // dalam km\n  estimatedTime Int? // dalam menit\n  estimatedCost Int? // dalam rupiah\n  isAiGenerated Boolean  @default(false)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  user  User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  items ItineraryItem[]\n}\n\n// Item dalam rencana perjalanan (urutan destinasi)\nmodel ItineraryItem {\n  id            Int      @id @default(autoincrement())\n  itineraryId   Int\n  destinationId Int\n  order         Int // urutan kunjungan (1, 2, 3, ...)\n  visitTime     String? // jam kunjungan yang direkomendasikan \"09:00\"\n  createdAt     DateTime @default(now())\n\n  itinerary   Itinerary   @relation(fields: [itineraryId], references: [id], onDelete: Cascade)\n  destination Destination @relation(fields: [destinationId], references: [id], onDelete: Cascade)\n\n  @@unique([itineraryId, order])\n}\n\n// Ulasan wisatawan\nmodel Review {\n  id            Int      @id @default(autoincrement())\n  userId        Int\n  destinationId Int\n  rating        Int // 1–5\n  comment       String?\n  photoUrl      String?\n  helpfulCount  Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  destination Destination @relation(fields: [destinationId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, destinationId]) // 1 user 1 review per destinasi\n}\n\n// Destinasi yang pernah dikunjungi (untuk fitur ulasan + geofencing)\nmodel VisitedPlace {\n  id            Int      @id @default(autoincrement())\n  userId        Int\n  destinationId Int\n  visitedAt     DateTime @default(now())\n  checkedIn     Boolean  @default(false) // geofencing auto check-in\n\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  destination Destination @relation(fields: [destinationId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, destinationId])\n}\n",
